begin;
select plan(34);
insert into public.universities(id,name,short_name) values ('61000000-0000-4000-8000-000000000001','팀플로그 테스트 대학','테스트대');
insert into public.university_email_domains(university_id,email_domain) values('61000000-0000-4000-8000-000000000001','team-fixture.example');
insert into auth.users(id,email,email_confirmed_at) values ('61000000-0000-4000-8000-000000000011','owner@team-fixture.example',now()), ('61000000-0000-4000-8000-000000000012','member@team-fixture.example',now()), ('61000000-0000-4000-8000-000000000013','visitor@team-fixture.example',now()), ('61000000-0000-4000-8000-000000000014','third@team-fixture.example',now());
insert into auth.identities(provider_id,user_id,provider,identity_data) select a.id::text,a.id,'google',jsonb_build_object('sub',a.id::text,'email',a.email,'email_verified',true,'custom_claims',jsonb_build_object('hd','team-fixture.example')) from auth.users a where a.email like '%@team-fixture.example';
insert into public.profiles(id,nickname,university_id,major,bio,skills,interests,preferred_category) select a.id,'팀플 테스터','61000000-0000-4000-8000-000000000001','디자인','테스트','{React}','{UX}','side_project' from auth.users a where a.email like '%@team-fixture.example';
insert into public.projects(id,owner_id,title,description,category) values('61000000-0000-4000-8000-000000000021','61000000-0000-4000-8000-000000000011','팀플로그 프로젝트','팀플로그 테스트 프로젝트입니다.','side_project');
insert into public.projects(id,owner_id,title,description,category) values('61000000-0000-4000-8000-000000000022','61000000-0000-4000-8000-000000000013','별도 팀플로그','별도 테스트 프로젝트입니다.','side_project');
insert into public.project_members (id,project_id,user_id,membership_role) values
 ('61000000-0000-4000-8000-000000000031','61000000-0000-4000-8000-000000000021','61000000-0000-4000-8000-000000000011','owner'),
 ('61000000-0000-4000-8000-000000000032','61000000-0000-4000-8000-000000000021','61000000-0000-4000-8000-000000000012','member'),
 ('61000000-0000-4000-8000-000000000034','61000000-0000-4000-8000-000000000021','61000000-0000-4000-8000-000000000014','member'),
 ('61000000-0000-4000-8000-000000000033','61000000-0000-4000-8000-000000000022','61000000-0000-4000-8000-000000000013','owner');
set local role authenticated;
set local request.jwt.claims='{"amr":[{"method":"oauth"}]}';
set local request.jwt.claim.sub='61000000-0000-4000-8000-000000000011';
select lives_ok($$select public.team_assign_role('61000000-0000-4000-8000-000000000021','61000000-0000-4000-8000-000000000032','디자인')$$,'팀장이 역할을 지정한다');
select set_config('test.team_task',public.team_create_task('61000000-0000-4000-8000-000000000021','테스트 작업','작업 설명',4,current_date,array['61000000-0000-4000-8000-000000000032']::uuid[])::text,true);
select set_config('test.feedback_round', public.team_open_feedback('61000000-0000-4000-8000-000000000021','중간 점검',now()+interval '1 day')::text,true);
select throws_ok($$select * from public.team_feedback_answers$$,'42501',null,'팀장도 원문과 작성자를 볼 수 없다');
select throws_ok($$select * from public.team_checkins$$,'42501',null,'팀장도 체크인 응답을 볼 수 없다');
select throws_ok($$select public.team_set_task_assignees(current_setting('test.team_task')::uuid,array['61000000-0000-4000-8000-000000000033']::uuid[])$$,'P0001','TEAM_INVALID_ASSIGNEES','다른 프로젝트 소속을 담당자로 지정할 수 없다');
select is(public.team_workbench('61000000-0000-4000-8000-000000000021')->'members'->1->>'role_name','디자인','팀 작업 공간에 배정된 역할을 표시한다');
select lives_ok($$select public.team_submit_feedback(current_setting('test.feedback_round')::uuid,5,3,null)$$,'팀장도 개인 피드백을 제출할 수 있다');
select lives_ok($$select public.team_submit_checkin('61000000-0000-4000-8000-000000000021',4,3,true)$$,'팀장도 개인 체크인을 제출할 수 있다');
set local request.jwt.claim.sub='61000000-0000-4000-8000-000000000012';
select lives_ok($$select public.team_set_task_status(current_setting('test.team_task')::uuid,'done')$$,'담당 팀원이 완료한다');
select throws_ok($$select public.team_assign_role('61000000-0000-4000-8000-000000000021','61000000-0000-4000-8000-000000000032','기획')$$,'P0001','PROJECT_OWNER_REQUIRED','팀원은 역할 배정 불가');
select lives_ok($$select public.team_submit_feedback(current_setting('test.feedback_round')::uuid,4,5,'중간 일정 조율 건의')$$,'팀원이 의견을 제출한다');
select throws_ok($$select public.team_submit_feedback(current_setting('test.feedback_round')::uuid,5,5,'다시 제출')$$,'P0001','TEAM_FEEDBACK_ALREADY_SUBMITTED','한 계정의 중복 피드백은 집계에 포함되지 않는다');
select lives_ok($$select public.team_submit_checkin('61000000-0000-4000-8000-000000000021',3,4,false)$$,'팀원이 주간 체크인에 응답한다');
select throws_ok($$select public.team_submit_checkin('61000000-0000-4000-8000-000000000021',3,4,true)$$,'P0001','TEAM_CHECKIN_ALREADY_SUBMITTED','주간 체크인은 계정당 한 번만 집계된다');
set local DateStyle to 'SQL, DMY';
select throws_ok($$select public.team_submit_checkin('61000000-0000-4000-8000-000000000021',3,4,true)$$,'P0001','TEAM_CHECKIN_ALREADY_SUBMITTED','세션의 날짜 표시 형식이 달라도 같은 주로 판정한다');
set local DateStyle to 'ISO, MDY';
select is(public.team_workbench('61000000-0000-4000-8000-000000000021')->'checkin'->'submitted','true'::jsonb,'내 체크인 제출만 확인할 수 있다');
select throws_ok($$select public.team_close_feedback(current_setting('test.feedback_round')::uuid)$$,'P0001','PROJECT_OWNER_REQUIRED','팀원은 설문을 종료할 수 없다');
set local request.jwt.claim.sub='61000000-0000-4000-8000-000000000014';
select throws_ok($$select public.team_set_task_status(current_setting('test.team_task')::uuid,'review')$$,'P0001','TEAM_TASK_ASSIGNEE_REQUIRED','담당하지 않는 팀원은 상태를 바꿀 수 없다');
select throws_ok($$select public.team_submit_feedback(current_setting('test.feedback_round')::uuid,0,5,null)$$,'P0001','TEAM_INVALID_SCORE','범위를 벗어난 점수는 집계하지 않는다');
select lives_ok($$select public.team_submit_feedback(current_setting('test.feedback_round')::uuid,3,4,null)$$,'세 번째 계정이 피드백을 제출한다');
select lives_ok($$select public.team_submit_checkin('61000000-0000-4000-8000-000000000021',2,5,false)$$,'세 번째 계정이 체크인을 제출한다');
select is(public.team_workbench('61000000-0000-4000-8000-000000000021')->'feedback'->0->'summary','null'::jsonb,'피드백은 응답이 충분해도 종료 전에는 숨긴다');
select is(public.team_workbench('61000000-0000-4000-8000-000000000021')->'checkin'->'summary','null'::jsonb,'진행 중인 주간 체크인의 중간 집계는 숨긴다');
set local request.jwt.claim.sub='61000000-0000-4000-8000-000000000011';
select lives_ok($$select public.team_close_feedback(current_setting('test.feedback_round')::uuid)$$,'팀장이 피드백 회차를 종료한다');
select is(public.team_workbench('61000000-0000-4000-8000-000000000021')->'feedback'->0->'summary','{"coordination_average":4.0,"communication_average":4.0}'::jsonb,'종료된 피드백에서 3명의 점수 평균만 볼 수 있다');
select ok(public.team_workbench('61000000-0000-4000-8000-000000000021')::text not like '%중간 일정 조율 건의%','작업 공간 응답에 익명 의견 원문이 없다');
select throws_ok($$select public.team_submit_feedback(current_setting('test.feedback_round')::uuid,5,3,null)$$,'P0001','TEAM_FEEDBACK_CLOSED','종료된 회차로는 제출할 수 없다');
select set_config('test.small_round', public.team_open_feedback('61000000-0000-4000-8000-000000000021','소수 응답 회차',now()+interval '1 day')::text,true);
select public.team_submit_feedback(current_setting('test.small_round')::uuid,1,2,null);
select public.team_close_feedback(current_setting('test.small_round')::uuid);
select is((select round_info->'summary' from jsonb_array_elements(public.team_workbench('61000000-0000-4000-8000-000000000021')->'feedback') round_info where round_info->>'id'=current_setting('test.small_round')),'null'::jsonb,'응답이 3명 미만인 종료 회차는 집계하지 않는다');
select lives_ok($$select public.team_set_task_assignees(current_setting('test.team_task')::uuid,array['61000000-0000-4000-8000-000000000034']::uuid[])$$,'팀장이 담당자를 바꿀 수 있다');
select is(public.team_workbench('61000000-0000-4000-8000-000000000021')->'tasks'->0->'assignees','["61000000-0000-4000-8000-000000000034"]'::jsonb,'팀 작업 공간에 변경된 담당자를 표시한다');
set local request.jwt.claims='{"amr":[{"method":"otp"}]}';
select throws_ok($$select public.team_workbench('61000000-0000-4000-8000-000000000021')$$,'P0001','VERIFIED_UNIVERSITY_REQUIRED','팀장도 검증된 학교 프로필로 접근해야 한다');
set local request.jwt.claims='{"amr":[{"method":"oauth"}]}';
set local request.jwt.claim.sub='61000000-0000-4000-8000-000000000013';
select throws_ok($$select public.team_workbench('61000000-0000-4000-8000-000000000021')$$,'P0001','PROJECT_MEMBER_REQUIRED','외부 사용자는 작업 공간을 볼 수 없다');
reset role;
select is((select count(*) from public.team_activity where project_id='61000000-0000-4000-8000-000000000021' and event_type in ('task_created','task_completed','task_updated')),3::bigint,'보고서의 허용 목록과 같은 작업 이벤트를 기록한다');
select is((select count(*) from public.team_activity where project_id='61000000-0000-4000-8000-000000000021' and (event_type ~ 'feedback|checkin' or details::text like '%중간 일정 조율 건의%')),0::bigint,'설문 원문·제출 여부·작성자는 활동 근거에 남기지 않는다');
update public.team_checkins set week_start=week_start-7 where project_id='61000000-0000-4000-8000-000000000021';
set local role authenticated;
set local request.jwt.claim.sub='61000000-0000-4000-8000-000000000011';
select is(public.team_workbench('61000000-0000-4000-8000-000000000021')->'checkin'->'summary','{"workload_average":3.0,"capacity_average":4.0,"needs_help":false}'::jsonb,'마감된 주의 평균을 집계하되 한 사람만의 도움 요청은 공개하지 않는다');
select * from finish();
rollback;
